import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>WebP 是谷歌为让网络更快而打造的格式，它确实管用。JPG 照片转成 WebP 通常能小 25% 到 35%，画质上看不出差别。</p>\n<p>省下来的体积很重要。图片更小意味着页面更快、访客更开心、搜索排名更好，这就是每个大网站现在都提供 WebP 的原因。</p>\n<p>这篇指南讲清 JPG 转 WebP 怎么工作、该用什么设置，以及什么时候该留着 JPG。</p>\n<h2 id=\"what-is-webp\">什么是 WebP？</h2>\n<p>WebP 是谷歌开发的图片格式，2010 年发布。从一开始就是为网络设计的，现代压缩在同等画质下胜过 JPG。</p>\n<p>这种格式同时支持有损和无损压缩，还支持透明。这套组合让它在很多网上用途里能替代 JPG、PNG 和 GIF。</p>\n<p>WebP 文件用 .webp 扩展名。它们看起来就是普通图片，现代浏览器不用插件或额外软件就能原生显示。</p>\n<p>谷歌推荐 WebP 用于更快的网站和更好的核心网页指标，也就是影响搜索排名的速度测量。</p>\n<h2 id=\"how-much-smaller\">WebP 比 JPG 小多少？</h2>\n<p>照片上，WebP 同等视觉画质下通常比 JPG 小 25% 到 35%。一张 1MB 的 JPG 照片变成 650KB 到 750KB 的 WebP。</p>\n<p>省多少因图片而异。细节丰富的风景省得少，因为要保留的纹理更多；平滑的人像省得多。</p>\n<p>有些图片省得更多。简单图形或大片纯色的截图转成 WebP，可能缩小一半以上。</p>\n<p>少数图片完全省不了。已经被重度压缩的 JPG 没多少可供 WebP 改善的空间，WebP 版本甚至可能略大一点。</p>\n<h2 id=\"how-conversion-works\">JPG 转 WebP 是怎么完成的？</h2>\n<p>转换器把 JPG 解码成像素，再按你选的画质把这些像素编码成 WebP。像素一样，压缩更现代。</p>\n<p>转换完全在浏览器里运行。照片永远不会上传到服务器，工作以本地处理器的速度进行。</p>\n<p>每张文件最大接受 25MB，涵盖高分辨率相机照片和大截图，不用任何准备。</p>\n<p>批量里每张独立转换，一张坏图不会拖垮其余文件。损坏的 JPG 显示错误标记，有效文件照常完成。</p>\n<h2 id=\"quality-settings\">真正管用的画质设置</h2>\n<p>网站照片用 75% 到 85% 的 WebP 画质，是最佳区间。图片看起来干净，文件小，页面加载快。</p>\n<p>80% 时，大多数照片和原 JPG 看不出差别。比 JPG 省得多，肉眼画质却一样。</p>\n<p>网店的产品照片用 80% 到 85%。顾客会放大看产品，多出来的画质能保护他们检查的细节。</p>\n<p>打算打印的照片，完全别用 WebP。打印机和打印店要的是 JPG 或 PNG，WebP 在纸上只增加兼容风险，没有任何好处。</p>\n<h2 id=\"browser-support\">哪些浏览器支持 WebP？</h2>\n<p>Chrome、Edge、Firefox、Safari、Opera 现在都原生支持 WebP。这覆盖了绝大多数网络流量。</p>\n<p>Safari 在 2020 年发布的 14 版里加入了支持。更早版本的旧 iPhone 和 Mac 显示不了 WebP，不过这类设备越来越少了。</p>\n<p>Internet Explorer 从不支持 WebP，但它已经停用，用量可以忽略。没有现代网站需要支持它。</p>\n<p>极少数用很老浏览器的访客，给他们提供 JPG 备用。现代网站用 picture 元素自动做到这一点。</p>\n<h2 id=\"dimensions-preserved\">尺寸与元数据</h2>\n<p>JPG 转 WebP 不改变像素尺寸。一张 4000×3000 的照片还是 4000×3000，变的只是格式和文件大小。</p>\n<p>EXIF 相机数据和 GPS 标签会在转换中清除。画到画布上会去掉元数据，在网上发布照片时能保护隐私。</p>\n<p>颜色配置文件由浏览器编码器处理。大多数照片的颜色保持准确，特别饱和的图片可能轻微偏移。</p>\n<p>输出文件名保留原名，换成 .webp 后缀。hero.jpg 会变成 hero.webp，很好找。</p>\n<h2 id=\"wordpress-shopify-wix\">在 WordPress、Shopify、Wix 里用 WebP</h2>\n<p>WordPress 从 5.8 版起支持 WebP 上传。转好的 WebP 文件可以直接上传到媒体库，像其他图片一样使用。</p>\n<p>Shopify 很多情况下会自动把上传的图片转成 WebP，但自己上传 WebP 文件能控制画质和大小。</p>\n<p>Wix 也支持 WebP。把转好的文件上传到媒体管理器，平台会以合适的格式提供给访客。</p>\n<p>任何平台都先测试一张图片。上传一张转好的 WebP，确认显示正确，再转换其余批量。</p>\n<h2 id=\"product-photos\">产品照片用 WebP</h2>\n<p>产品照片用 WebP 受益巨大。网店有几百张产品图，每张小 30%，快速网店和慢速网店的区别就在这里。</p>\n<p>顾客会放大看产品，画质保持在 80% 到 85%。画质低了会糊掉买家检查的精细细节，比如布料纹理和缝线。</p>\n<p>整个目录一次批量转换。转换器处理混合文件夹，ZIP 里装着每张准备上传的 WebP。</p>\n<p>JPG 原文件也留着。某个平台要求 JPG 时，可以直接上传它们，不用重新转换。</p>\n<h2 id=\"screenshots-with-text\">带文字的截图</h2>\n<p>同样文件大小下，WebP 比 JPG 更能保留文字。截图转 85% 的 WebP，字母保持可读，JPG 版本则会把它们糊掉。</p>\n<p>这让 WebP 成为博客截图、文档图片、教程图形的更好选择，因为文字就是内容。</p>\n<p>每个字母都必须完美的截图，比如法律证据，考虑用无损 WebP 或 PNG。有损 WebP 很好，但不是完美的。</p>\n<p>下载前用“对比”查看器检查结果。放大最小的文字，确认读起来干净。</p>\n<h2 id=\"when-webp-is-larger\">WebP 反而更大时</h2>\n<p>偶尔转好的 WebP 比原 JPG 大。简单或已经被压缩过的 JPG 会出现这种情况，WebP 没多少可省的空间。</p>\n<p>画质设置得非常高时也会这样。95% 画质的 WebP 可能超过它来源的 JPG，因为编码器在保留几乎所有东西。</p>\n<p>WebP 更大时，留着 JPG。没有规则说 WebP 必须永远赢，目标是更小的文件，而不是某种特定格式。</p>\n<p>检查每张卡片上的转换前后大小。转换器同时显示两个数字，决定一目了然。</p>\n<h2 id=\"when-to-keep-jpg\">什么时候留着 JPG</h2>\n<p>目的地要求时留着 JPG。有些上传表格、打印机、老程序明确列出 JPG，拒收 WebP。</p>\n<p>邮件附件留着 JPG。邮件客户端显示 JPG 很可靠，WebP 在邮件里的支持在各个应用里还不一致。</p>\n<p>照片还要继续编辑时留着 JPG。大多数修图软件原生处理 JPG，WebP 在桌面修图软件里的支持还在追赶。</p>\n<p>观众用很老的设备时留着 JPG。JPG 在有史以来做的每台设备上都能打开，WebP 需要近几年的浏览器。</p>\n<h2 id=\"checking-quality\">下载前检查画质</h2>\n<p>点任意卡片上的“对比”，并排查看原 JPG 和转好的 WebP。拖动分割线，仔细检查图片。</p>\n<p>先检查脸部、文字和精细细节。低画质最先在这些地方露馅，花十秒检查能及早发现问题。</p>\n<p>第一次转换后，不用重新上传就能改画质。原文件还留在队列里，换个设置再对比一次就行。</p>\n<p>批量时检查三四张有代表性的文件，而不是每一张。这几张没问题，其余的也会没问题，因为设置相同。</p>\n<h2 id=\"webp-for-blogs\">博客用 WebP</h2>\n<p>博客图片是经典的 WebP 使用场景。一篇博客文章十张照片，转成 WebP 后加载快得多，读者在快速页面上停留更久。</p>\n<p>博客的 JPG 照片转 80% 画质的 WebP。图片看起来一样，文件缩小三分之一，页面感觉明显更快。</p>\n<p>博客带文字的截图用 85% 的 WebP，字母保持可读。同样大小下，文字比 JPG 更锐利，教程图片尤其需要这一点。</p>\n<p>转换后更新图片引用，测试文章。坏掉的图片引用比慢速图片更糟，所以检查页面上的每张图片。</p>\n<p>媒体库里留着 JPG 原文件做备用。读者浏览器显示不了 WebP 时加载 JPG 版本，没人会看到破损图片。</p>\n<h2 id=\"webp-for-shops\">网店用 WebP</h2>\n<p>网店靠图片活着。几百张产品照片，每张转成 WebP 小三分之一，快速网店和慢速网店的区别就在这里。</p>\n<p>产品照片转 80% 到 85% 画质的 WebP。顾客会放大看产品，多出来的画质能保护他们检查的精细细节。</p>\n<p>产品缩略图用 75% 画质就够了。缩略图很小，柔和看不见，分类页面瞬间加载。</p>\n<p>转换后在手机上测试网店。现在移动购物者是多数，慢速连接上的快速网店比慢速网店转化率高得多。</p>\n<p>切换前后测量网店速度。加载时间上的具体改善，能向整个团队证明转换工作值得。</p>\n<h2 id=\"webp-for-portfolios\">作品集用 WebP</h2>\n<p>作品集必须看起来完美，WebP 能以更小的体积做到这一点。摄影师二十张图片的作品集，转成 WebP 几秒加载完，转成 JPG 却要几分钟。</p>\n<p>作品集图片用 85% 画质。照片就是产品，多出来的画质能保护客户评判你的细节。</p>\n<p>作品集主图用 80% 就够了。图片铺满屏幕，文件依然小，每个访客的页面加载都很快。</p>\n<p>JPG 原文件也留着，有些客户会要它们。客户要一张 JPG 做演示时，直接给就行，不用重新转换。</p>\n<p>定期更新作品集，加新作品时就转换。作品集里 JPG 和 WebP 混在一起会变得不一致，统一的 WebP 组合一直很快。</p>\n<h2 id=\"webp-for-news\">新闻网站用 WebP</h2>\n<p>新闻网站每天发布几十张图片，体量让 WebP 的节省变得巨大。一篇文章五张图片能省好几 MB，首页五十张省得更多。</p>\n<p>新闻照片转 80% 画质的 WebP。图片看起来干净，页面加载快，移动网络上的读者留下来了，而不是离开。</p>\n<p>突发新闻时，速度最重要。WebP 图片上传和加载都比 JPG 快，新闻能更快到达读者，这就是新闻的意义。</p>\n<p>可能的话，在发布流程里自动转换。自动转换的新闻编辑部永远不会忘，手动步骤在截止时间压力下会被跳过。</p>\n<p>给老读者留 JPG 备用。picture 元素给现代浏览器提供 WebP、给其他浏览器提供 JPG，每个读者都能看到图片。</p>\n<h2 id=\"measuring-speed-improvement\">测量速度提升</h2>\n<p>转换前先测量页面速度，改善才具体。PageSpeed Insights 这类工具能给出页面的分数和加载时间。</p>\n<p>转换图片，再测一次。四秒加载的页面可能变成三秒，访客马上就能感觉到。</p>\n<p>总页面重量也要检查。JPG 时 10MB 的页面，转成 WebP 可能 7MB，数字上的改善看得见。</p>\n<p>在慢速移动网络上测试，不只是在快速办公室 Wi-Fi 上。改善最大的地方正是最重要的地方，也就是真实访客实际用的连接。</p>\n<p>把数字分享给团队。具体的速度提升能证明转换工作值得，鼓励大家给新图片也用 WebP。</p>\n<h2 id=\"webp-for-documentation-sites\">文档网站用 WebP</h2>\n<p>文档网站满是截图，WebP 能以 PNG 的零头体积保持它们可读。几百张截图的文档网站转成 WebP 后，加载快得多。</p>\n<p>文档截图转 85% 画质的 WebP。文字保持可读，文件大幅缩小，页面感觉明显更快。</p>\n<p>每个字母都必须完美的截图，比如 API 参考，考虑用无损 WebP 或 PNG。有损 WebP 很好，但不是完美的。</p>\n<p>转换后更新图片引用，测试文档网站。坏掉的图片引用比慢速图片更糟，更新后检查每一页。</p>\n<p>文档仓库里留着 PNG 原文件做备用。读者浏览器显示不了 WebP 时加载 PNG 版本，没人会看到破损图片。</p>\n<p>准备好让网站更快了吗？打开<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>，把照片拖进去。分步操作请读<a href=\"/zh/blog/ruhe-ba-jpg-zhuancheng-webp/\">如何把 JPG 转换成 WebP</a>，正面对决请看<a href=\"/zh/blog/jpg-vs-webp/\">JPG 与 WebP 对比</a>。照片是 PNG 截图时，<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>是对应的工具。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"同样照片，WebP 比 JPG 小多少？","answer":"同等视觉画质下通常小 25% 到 35%。一张 1MB 的 JPG，80% 画质下变成 650KB 到 750KB 的 WebP。省多少因图片而异：平滑人像省得多，细节风景省得少，已经压缩过的 JPG 可能完全省不了。"},{"question":"JPG 转 WebP 会改变照片尺寸吗？","answer":"不会。转换保留原 JPG 精确的像素宽高，变的只是格式和文件大小。还需要更小的尺寸时，先用图片尺寸调整工具改尺寸，再把改好尺寸的副本转成 WebP。"},{"question":"WordPress 里能用 WebP 图片吗？","answer":"可以。WordPress 从 5.8 版起支持 WebP 上传，转好的 WebP 文件在媒体库里像其他图片一样使用。先上传一张测试图片确认显示正确，再转换、上传其余批量。"},{"question":"网站照片用什么画质设置好？","answer":"80% 是大多数网站照片的好默认值，体积和画质平衡得很好。加载速度最重要的的大图用 75%，访客会放大的产品照片用 85%。别低于 70%，低于这个值柔和就看得见了。"},{"question":"手机上能把 JPG 转成 WebP 吗？","answer":"可以。在手机浏览器里打开转换器，从相册里选 JPG，下载 WebP 文件就行。转换在手机上运行，文件下载到设备里。手机上的批量保持适中，大照片在移动端编码很花时间。"},{"question":"为什么转好的 WebP 比原 JPG 还大？","answer":"简单或已经被压缩过的 JPG 会出现这种情况，WebP 没多少可省的空间，95% 这类很高画质设置下也会这样。WebP 更大时，留着 JPG 就行。检查每张卡片上的转换前后大小，让数字决定。"}];
